SELECT status, DATE_TRUNC('MONTH', delivered_date) delivered_month, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) status_values, ROUND(STDDEV(cost), 2) stddev_cost, ROUND((100 * SUM(CASE WHEN status = 'DELIVERED' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_delivered FROM shipments WHERE cost BETWEEN 31 AND 48 AND carrier <> 'DHL' AND status NOT IN ('IN_TRANSIT', 'DELIVERED', 'RETURNED') GROUP BY status, DATE_TRUNC('MONTH', delivered_date) HAVING ROUND((100 * SUM(CASE WHEN status = 'DELIVERED' THEN 1 ELSE 0 END)) / COUNT(*), 1) >= 77 ORDER BY pct_delivered DESC
